1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.Valid;
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
14	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
15	import org.springframework.samples.petclinic.rest.escalation.RegistrationDateInFutureException;
16	import org.springframework.validation.annotation.Validated;
17	import org.springframework.web.bind.annotation.RequestBody;
18	
19	@Validated
20	public class BuildOwner {
21	
22	    /** Simple syntactic email check: non-space local part, '@', non-space domain with a dot. */
23	    private static final java.util.regex.Pattern EMAIL =
24	            java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
25	
26	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper,
27	            OwnerRepository ownerRepository, Out<Owner> built, Out<Boolean> sharesHousehold)
28	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
29	            RegistrationDateInFutureException {
30	        List<String> missing = new ArrayList<>();
31	        // Normalize the address up front so the required-field check rejects an address that is
32	        // blank once trimmed/collapsed, and every later step (and the stored value) sees the
33	        // canonical form.
34	        String normalizedAddress = AddressNormalizer.normalize(request.getAddress());
35	        if (isBlank(request.getFirstName())) {
36	            missing.add("firstName");
37	        }
38	        if (isBlank(request.getLastName())) {
39	            missing.add("lastName");
40	        }
41	        if (normalizedAddress.isEmpty()) {
42	            missing.add("address");
43	        }
44	        if (isBlank(request.getCity())) {
45	            missing.add("city");
46	        }
47	        if (isBlank(request.getTelephone())) {
48	            missing.add("telephone");
49	        }
50	        if (!missing.isEmpty()) {
51	            throw new MissingOwnerFieldsException(missing);
52	        }
53	        request.setTelephone(TelephoneNormalizer.normalize(request.getTelephone()));
54	        request.setAddress(normalizedAddress);
55	        request.setEmail(normalizeEmail(request.getEmail()));
56	        Owner owner = ownerMapper.toOwner(request);
57	        // The EFFECTIVE registration date (supplied or defaulted to the server date) must fall on
58	        // a business day: a Saturday or Sunday rolls forward to the next Monday. Every value
59	        // derived from the registration date (e.g. the membership number's year segment, the daily
60	        // create-limit's day) then uses this adjusted date.
61	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
62	        java.time.LocalDate serverDate = java.time.LocalDate.now();
63	        if (registrationDate == null) {
64	            registrationDate = serverDate;
65	        } else if (registrationDate.isAfter(serverDate)) {
66	            // A supplied registration date cannot be in the future.
67	            throw new RegistrationDateInFutureException(registrationDate, serverDate);
68	        }
69	        owner.setRegistrationDate(toBusinessDay(registrationDate));
70	        owner.setCustomerCode(CustomerCode.of(owner));
71	        built.set(owner);
72	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
73	    }
74	
75	    /**
76	     * Roll a registration date off the weekend: a Saturday or Sunday moves forward to the next
77	     * Monday; a weekday is returned unchanged.
78	     */
79	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
80	        switch (date.getDayOfWeek()) {
81	            case SATURDAY:
82	                return date.plusDays(2);
83	            case SUNDAY:
84	                return date.plusDays(1);
85	            default:
86	                return date;
87	        }
88	    }
89	
90	    /** When present, require a syntactically valid address and store it lower-cased; else reject with 400. */
91	    private static String normalizeEmail(String email) throws InvalidEmailException {
92	        if (email == null || email.isBlank()) {
93	            return null;
94	        }
95	        String trimmed = email.trim();
96	        if (!EMAIL.matcher(trimmed).matches()) {
97	            throw new InvalidEmailException(email);
98	        }
99	        return trimmed.toLowerCase(java.util.Locale.ROOT);
100	    }
101	
102	    private static boolean isBlank(String value) {
103	        return value == null || value.isBlank();
104	    }
105	}
