9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Settles the household id for a new owner. When the request opted in with
16	 * {@code sharesHousehold} true and an existing owner shares its normalized last name and
17	 * address (see {@link AddressNormalizer}), the two share a household: a stable
18	 * {@code householdId} is stamped on the new owner and on every existing member, and the
19	 * household's size is recorded on all of them. Otherwise the owner is a household of one.
20	 *
21	 * <p>This step no longer rejects duplicates — a shared last name and address is not itself a
22	 * conflict. All duplicate detection is now the single {@link CheckOwnerIdentityUnique} step,
23	 * which compares the whole {@link OwnerIdentity#key(Owner) identityKey}. Because the household
24	 * id set here is part of that key, two members of the same household with different telephones
25	 * have different keys and are both allowed. Runs after {@link BuildOwner}.
26	 */
27	public class AssignOwnerHousehold {
28	
29	    public void service(@Val Owner owner, @Val Boolean sharesHousehold,
30	            OwnerRepository ownerRepository) {
31	        owner.setHouseholdSize(1); // a household of one until an existing member is found
32	        if (!Boolean.TRUE.equals(sharesHousehold)) {
33	            return; // did not opt in: never joins an existing household
34	        }
35	        String lastName = key(owner.getLastName());
36	        String address = AddressNormalizer.normalize(owner.getAddress());
37	        List<Owner> household = new ArrayList<>();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
40	                continue; // same record (e.g. re-save)
41	            }
42	            if (lastName.equals(key(existing.getLastName()))
43	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
44	                household.add(existing);
45	            }
46	        }
47	        if (household.isEmpty()) {
48	            return; // no existing owner at this last name + address
49	        }
50	        // Assign the same stable household identifier to all members, and record the household's
51	        // size (existing members plus this new owner) on every member so it reflects the
52	        // household as it stands after this create.
53	        String householdId = householdId(lastName, address, household);
54	        int householdSize = household.size() + 1;
55	        owner.setHouseholdId(householdId);
56	        owner.setHouseholdSize(householdSize);
57	        for (Owner member : household) {
58	            member.setHouseholdId(householdId);
59	            member.setHouseholdSize(householdSize);
60	            ownerRepository.save(member);
61	        }
62	    }
63	
64	    /**
65	     * The household's stable shared identifier: reuse the id an existing member already carries
66	     * (so a household keeps one value over time); otherwise derive it deterministically from the
67	     * normalized last name and address, so independent joiners compute the same value.
68	     */
69	    private static String householdId(String lastName, String address, List<Owner> household) {
70	        for (Owner member : household) {
71	            String existing = member.getHouseholdId();
72	            if (existing != null && !existing.isBlank()) {
73	                return existing;
74	            }
75	        }
76	        return "H-" + sha256Hex(lastName + "\n" + address).substring(0, 12).toUpperCase(Locale.ROOT);
77	    }
78	
79	    private static String sha256Hex(String value) {
80	        try {
81	            byte[] digest = MessageDigest.getInstance("SHA-256")
82	                    .digest(value.getBytes(StandardCharsets.UTF_8));
83	            StringBuilder sb = new StringBuilder(digest.length * 2);
84	            for (byte b : digest) {
85	                sb.append(String.format("%02x", b));
86	            }
87	            return sb.toString();
88	        }
89	        catch (NoSuchAlgorithmException e) {
90	            throw new IllegalStateException("SHA-256 not available", e);
91	        }
92	    }
93	
94	    /** Comparison key: lower-cased, with leading/trailing and repeated whitespace collapsed. */
95	    private static String key(String value) {
96	        if (value == null) {
97	            return "";
98	        }
99	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
100	    }
101	}
