21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
23	                continue; // same record (e.g. re-save), not a conflict
24	            }
25	            if (identityKey.equals(OwnerIdentity.key(existing))) {
26	                throw new DuplicateIdentityException(identityKey);
27	            }
28	        }
29	    }
30	}
