19	    /** Maximum number of owners that may be created in a single day. */
20	    private static final int DAILY_LIMIT = 100;
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
23	            throws DailyOwnerLimitException {
24	        // Count against the new owner's (already business-day-adjusted) registration date, not the
25	        // raw server date, so the limit applies per adjusted business day.
26	        LocalDate registrationDate = owner.getRegistrationDate();
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
30	                continue; // the owner being created is not counted against the limit
31	            }
32	            if (registrationDate.equals(existing.getRegistrationDate())) {
33	                count++;
34	            }
35	        }
36	        if (count >= DAILY_LIMIT) {
37	            throw new DailyOwnerLimitException(count);
38	        }
39	    }
40	}
