3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single derived duplicate-detection key for an owner. All duplicate detection on create
9	 * flows through this one value: the normalized (E.164) telephone, a {@code '|'}, the email
10	 * (lower-cased and trimmed, or empty when absent), a {@code '|'}, and the household id (or
11	 * empty). Two owners are duplicates only when their WHOLE key is equal — so, because the
12	 * telephone is part of the key, two members of the same household (same household id) with
13	 * different telephones have different keys and are both allowed.
14	 */
15	public final class OwnerIdentity {
16	
17	    private OwnerIdentity() {
18	    }
19	
20	    public static String key(Owner owner) {
21	        return telephone(owner.getTelephone()) + "|" + email(owner.getEmail()) + "|"
22	                + household(owner.getHouseholdId());
23	    }
24	
25	    /** Normalized telephone: the E.164 form used everywhere else (see {@link TelephoneNormalizer}). */
26	    private static String telephone(String telephone) {
27	        return telephone == null ? "" : TelephoneNormalizer.comparisonKey(telephone);
28	    }
29	
30	    /** Email lower-cased and trimmed; a null/blank email contributes the empty string. */
31	    private static String email(String email) {
32	        return email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
33	    }
34	
35	    /** The owner's household id, or empty when the owner is not part of a shared household. */
36	    private static String household(String householdId) {
37	        return householdId == null ? "" : householdId.strip();
38	    }
39	}
